export default [{"id":389,"question":"أنا مقيمٌ في مكة منذ الصغر، وكل سنة أحج حتى بلغت الثامنة عشر، هل أديتُ الفريضة أم لا؟","title":"ما العمر الذي يجزئ فيه الحج عن الفريضة؟","answer":"الجواب: الحجة التي صادفت بلوغه هي حجّة الفريضة، بعدما كمل خمسة عشر سنة، أو صادفته بعدما احتلم وأنزل، أو أنبت الشعر الخشن حول الفَرْج، فالحجّة التي بعد هذا هي حجة الفريضة، والباقي نافلة، والتي قبلها نافلة كذلك.","link":"https://binbaz.org.sa/fatwas/4765/ما-العمر-الذي-يجزى-فيه-الحج-عن-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0445.mp3","categories":["شروط الحج"]},{"id":391,"question":"ما حكم حج المديون؟ مع العلم أنه سدد جزءًا كبيرًا من دينه، ووجد فرصةً حسنةً لأداء الفريضة ووجود تذاكر سفر مجانًا؟","title":"حكم من حج وعليه دَيْن","answer":"الجواب: حجّه صحيح، لا شيء في ذلك، لكن ينبغي له أن يبدأ بالدين، ولا يُسمَّى: مُستطيعًا وهو عاجزٌ عن قضاء دينه، ولكن لو حجَّ وأخَّر الدَّين فحجّه صحيح، ولكنه أساء في تقديم الحج على قضاء الدَّين؛ لأنه غير مُستطيعٍ في الحقيقة، غير مطالبٍ حتى يستطيع ذلك بقضاء الدَّين ووجوب النَّفقة التي تُعينه على ذلك، ولو حجَّ وتجشم المشقَّة وعليه دَيْنٌ؛ صحَّ حجه.","link":"https://binbaz.org.sa/fatwas/4775/حكم-من-حج-وعليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0447.mp3","categories":["شروط الحج"]},{"id":618,"question":"شرط المحرم للمرأة في الحج للوجوب؟","title":"هل المحرم للمرأة شرط في الحج؟","answer":"الجواب: نعم لا يجب عليها الحج إلا بمحرم، ولا يجوز لها السفر إلا بمحرم.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6458/هل-المحرم-للمراة-شرط-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/maram186 - 01 - .mp3","categories":["شروط الحج"]},{"id":620,"question":"إذا البلوغ إذا كان في الحج؟","title":"هل يجزئ الحج عمن بلغ قبل عرفة؟","answer":"الجواب: إذا بلغ قبل عرفة؛ أجزأه. إذا أدرك عرفة وهو قد بلغ، الحمد لله.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6460/هل-يجزى-الحج-عمن-بلغ-قبل-عرفة","audio":"https://files.zadapps.info/binbaz.org.sa/maram188 - .mp3","categories":["شروط الحج"]},{"id":2709,"question":"مَن استدان للحج أو العمرة يصح حجُّه؟","title":"ما حكم الاستدانة للحج أو العمرة؟","answer":"الجواب: يصح نعم، لكن لا يُشرع له الاستدانة، الحج والعمرة مع الاستطاعة، لا حاجة للاستدانة؛ إن استطاع وإلا الحمد لله معفو عنه، لا يتكلّف.","link":"https://binbaz.org.sa/fatwas/22851/ما-حكم-الاستدانة-للحج-او-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يصح الاستدان للحج أو العمرة.mp3","categories":["شروط الحج"]},{"id":4636,"question":"استطاع الوصول ولم يكن عنده مالٌ للرجوع؟","title":"حكم من حج وليس عنده مالٌ للرجوع؟","answer":"الجواب:\nلا بدَّ أن تكون عنده استطاعة للسبيلين: ذهاب، وإياب.","link":"https://binbaz.org.sa/fatwas/24926/حكم-من-حج-وليس-عنده-مال-للرجوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الاستطاعة في الحج.mp3","categories":["شروط الحج"]},{"id":4637,"question":"النَّفقة على أهله داخلة في الاستطاعة؟","title":"هل يلزم الحاج نفقة كافية لأهله حتى يرجع؟","answer":"الجواب: إلزامًا عليه النَّفقة، حتى يرجع، يُنفق على مَن بقي من أهله.","link":"https://binbaz.org.sa/fatwas/24927/هل-يلزم-الحاج-نفقة-كافية-لاهله-حتى-يرجع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل النفقة على الأهل داخلة في الاستطاعة.mp3","categories":["شروط الحج"]},{"id":4780,"question":"هل الزوج ملزم بأن يحجج زوجته بعد الاستطاعة؟","title":"هل يلزم الزوج المستطيع حج زوجته؟","answer":"ليس ملزمًا، إنما عليها الحج هي إذا استطاعت هي، أما زوجها ما هو ملزم، إذا كانت غير مستطيعة لا يلزمها الحج لكون زوجا مستطيعًا، لا، لا يلزمه. لكن إذا أحسن إليها وحججها؛ فهذا من المعروف ومن مكارم الأخلاق، وإلا ما يلزمه، إنما يلزمها هي إذا استطاعت.","link":"https://binbaz.org.sa/fatwas/25145/هل-يلزم-الزوج-المستطيع-حج-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يلزم الزوج أن يحجج زوجته بعد الاستطاعة.mp3","categories":["شروط الحج"]},{"id":5046,"question":"إذا حجَّ إنسانٌ وعنده دَيْنٌ، هل يُقْبَل حجّه؟","title":"هل يُقْبَل حجّ من عليه دَيْنٌ؟","answer":"الجواب: يُقْبَل إن شاء الله، لكن إذا كان الدَّين حالًّا وهو عاجز يبَدِّي (يُقدِّم) الدَّينَ، وإلا فحجّه صحيح، لكن الأفضل له أن يبدأ بالدَّين.","link":"https://binbaz.org.sa/fatwas/29280/هل-يقبل-حج-من-عليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُقْبَل حجّ من عليه دينٌ؟.mp3","categories":["شروط الحج"]},{"id":7530,"question":"هذه الرسالة تتعلق بالحج أيضاً وسعد زيد الشامي، الثقبة، المنطقة الشرقية. يقول: حجيت بزوجتي، وعرضت علي زوجتي ذهاب أختها معنا للحج وأردت الامتناع؛ لأن أختها ليست محرماً لي، إلا أني خشيت بأن تظن زوجتي أني لا أريد أختها تحج معنا فقط، أفيدونا عن حكم ذهاب أخت زوجتي معنا، وما حكم حجها هذا؟ هل يكفي عن حجة الإسلام جزاكم الله خيراً؟","title":"حكم سفر المرأة مع زوج أختها للحج","answer":"الجواب: الجواب يا أيها السائل: لا شك أن سفر المرأة بدون محرم أمر لا يجوز، فقد صح عن رسول الله عليه الصلاة والسلام أنه قال: لا تسافر المرأة إلا مع ذي محرم فوجب على المسلمين امتثال أمر الله وأمر رسوله عليه الصلاة والسلام، فلا يجوز للمرأة أن تسافر للحج ولا لغيره إلا بمحرم، وهو أخوها، أو عمها، أو أبوها، أو زوجها، فأخت الزوجة ليست محرماً لست لها محرماً، فليس لها أن تسافر معك، ولو غضبت أختها فليس لها أن تسافر معك إما للحج ولا غيره، ولك أن تعتذر بالأمر الشرعي وتقول: لا يسعني أن تسافري معنا، ولست لي بمحرم، وهذا هو الواجب عليك، وعليها الاقتناع بأمر الله وبحكم الله ، لكن لو حجت بغير محرم حجها صحيح، وعليها التوبة والاستغفار مما تعاطت من الإثم، والحج صحيح؛ لأنه وقع موقعه، لكن الوسيلة إليه غير جائزة، فعليها التوبة إلى الله من ذلك والاستغفار، وحجها صحيح.","link":"https://binbaz.org.sa/fatwas/4504/حكم-سفر-المراة-مع-زوج-اختها-للحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_010/01008.mp3","categories":["شروط الحج"]},{"id":8069,"question":"هذا سؤال في نفس الرسالة، بعث به المستمع يحيى يحيى هزازي ابن عم الأول، يقول في سؤاله هذا: إذا نويت أن أحج وقمت ببيع بعض المواشي، واقترضت من أي إنسان مبلغ، فهل يتم الحج أو لا يجوز أفيدونا جزاكم الله خيراً؟","title":"حكم الاقتراض لتأدية فريضة الحج","answer":"الجواب: لا بأس إذا اقترضت شيئاً فلا بأس، إذا كان عندك ما يسدده بعد الرجوع فلا بأس، وأما إذا كان ما عندك شيء فالأولى أن لا تقترض وأنت بحمد الله معذور؛ لأن الحج إنها يجب مع الاستطاعة، والذي لا يستطيع إلا بالقرض والاستدانة غير مستطيع، لكن إذا كان عندك بحمد الله ما تستطيع أن توفي منه، من غلة عقار، ومن تجارة ومن غير ذلك، فلا بأس ولا حرج أن تستدين أو تقترض وتحج، كل ذلك لا حرج فيه، والحج صحيح والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/5865/حكم-الاقتراض-لتادية-فريضة-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_083/08310.mp3","categories":["شروط الحج"]},{"id":8100,"question":"رسالة باعثها أحد الإخوة فيما يبدو من لهجة الرسالة أنه سوداني، يكتبها بلهجته العامية، إنما معناها سماحة الشيخ، يقول: إنه قد أخبر من أحد الإخوان أن من أفطر عمداً لا يصح له حج، ماذا يقول الشيخ لمثل هذا؟","title":"حكم حج من أفطر عامداً في رمضان","answer":"الجواب: هذه الفتوى خطأ، إذا أفطر في رمضان عامداً فقد عصى ربه ولكن هذه المعصية لا تمنع الحج، ولا تبطل الحج وإنما عليه التوبة إلى الله من ذلك وقضاء اليوم الذي أفطره، فإذا أفطر يوما من رمضان بغير عذر شرعي فقد أتى منكراً عظيماً ومن تاب تاب الله عليه، فعليه التوبة إلى الله بصدق بأن يندم على ما مضى، ويعزم أن لا يعود، ويستغفر ربه كثيراً، ويبادر بقضاء اليوم الذي أفطره وحجه صحيح إذا حج، وإن قد كان حج سابقاً فحجه صحيح أيضاً ولا يبطله إفطاره يوماً من رمضان، إنما هو معصية وكبيرة من كبائر الذنوب فعليه التوبة إلى الله من ذلك، كما أن المعاصي الأخرى لا تبطل الحج كما لو زنى أو شرب الخمر أو عق والديه أو أحدهما أو أكل الربا أو ما أشبه ذلك من المعاصي كلها لا تبطل حجه، وإنما يبطل الحج بالجماع إذا جامع قبل التحلل الأول، إذا جامع قبل رمي الجمرة وقبل الطواف وقبل الحلق أو التقصير بأن جامع بعد الإحرام أو في عرفة أو بعد عرفة قبل أن يتحلل هذا هو الذي يبطل الحج، أما جنس المعاصي فلا تبطل الحج، وهكذا لو كفر والعياذ بالله أو ارتد عن دينه، إذا ارتد عن دينه ومات على ذلك بطلت أعماله، أما لو ارتد عن دينه ثم أسلم وهداه الله فإنها تبقى له أعماله إذا مات على الإسلام. نعم.","link":"https://binbaz.org.sa/fatwas/5896/حكم-حج-من-افطر-عامدا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_101/10105.mp3","categories":["شروط الحج"]},{"id":8175,"question":"شيخ عبد العزيز أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من منطقة الليث شركة الكهرباء، وباعثها أخونا علي عيسى الزهراني، أخونا له سؤال مطول يقول فيه: لقد حجت والدتي مع ولد أخيها وأمه، وعندما بدأ في طواف القدوم ومع شدة الزحام تفرقوا وذهب الولد بعيدًا، وأصبحت والدتي ووالدته بدون محرم إلا أنهن أتممن بقية النسك مع أناس معروفين لدينا في القرية إلا أنهم -كما قلت- ليسوا بمحارم، ولكن خوفًا عليهن من الضياع ولكبر السن حيث يتجاوزن الخمسة والأربعين عامًا، ولبعد مكاننا عن مكة المكرمة وخوفهن من ضياع الوقت في البحث عن ذلك الولد أكملن الحج، ولم يتقابلن مع الولد إلا بعد انتهاء الحج، فما حكم ما فعلن؟ وهل تأثر حجهن أو لا؟ نرجو توضيح ذلك، ولكم الأجر والثواب؟","title":"حكم حج المرأة دون محرم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كان الواقع هو ما ذكره السائل، فحجهن صحيح، وليس من شرط الطواف، أو السعي، أو رمي الجمار، أو الوقوف بعرفة، أو في مزدلفة ليس من شرط ذلك المحرم، فالمحرم إنما هو شرط في السفر لا يسافرن إلا بمحرم، أما كونهن يؤدين الأنساك بدون محرم فلا يضرهن ذلك، فإذا وقفت المرأة في عرفات وليس معها محرمها، أو في مزدلفة، أو رمت الجمار، أو طافت، أو سعت وليس معها محرمها فلا حرج في ذلك، وحجهن صحيح ورميهن صحيح، ووقوفهن صحيح والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/5981/حكم-حج-المراة-دون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_105/10501.mp3","categories":["شروط الحج"]},{"id":8412,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية، باعثها أخونا فايز محمد جابر ، أخونا يسأل ويقول: هل يصح الحج من شخص عمره ثلاثون عاماً؟","title":"وقت إجزاء الإنسان فريضة الحج عن نفسه","answer":"الجواب: نعم، كل من بلغ الحلم صح حجه عن نفسه وأدى الفريضة بذلك، ولو كان ابن خمسة عشر سنة أو أقل أو أكثر، فالمقصود إذا كان مكلفاً قد بلغ الحلم بإكماله خمسة عشر سنة، أو بإنزاله المني في الاحتلام أو في اليقظة عن شهوة، أو بإنباته الشعر الخشن حول الفرج؛ فإنه بهذا يكون مكلفاً، وإذا حج في هذه الحال أو بعدها فإن حجه يكون صحيحاً ومؤدياً للفريضة.\nأما إذا كان حجه قبل البلوغ وهو صغير؛ فإنه يعتبر حجاً تطوعاً متنفل نافلة، ولا يؤدي عنه حجة الإسلام إلا إذا كان أداؤه له بعد البلوغ، وليس له حد محدود من جهة السن، المهم أن يكون بالغاً، والبلوغ يكون بأحد ثلاثة أمور: إما إكمال خمسة عشر سنة في أصح قولي العلماء وهو قول الجمهور، وإما بإنبات الشعر الخشن حول الفرج، وإما بالاحتلام بإنزال المني حال النوم أو في اليقظة عن شهوة؛ كتفكير أو بسبب النظر أو اللمس فينزل المني عن شهوة، فهذا يكون بذلك بالغاً يكون مكلفاً.\nوالمرأة مثل ذلك، إذا بلغت خمسة عشر سنة، أو أنبتت الشعرة حول الفرج، الشعر الخشن المعروف، أو أنزلت بالاحتلام أو بغيره عن شهوة، وتزيد أمراً رابعاً وهو الحيض، فإذا وجد منها واحد من هذه الأربعة صارت مكلفة، وصح حجها فريضة، وقبل ذلك يكون نافلة، لا يؤدي الفريضة. نعم.","link":"https://binbaz.org.sa/fatwas/6296/وقت-اجزاء-الانسان-فريضة-الحج-عن-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11803.mp3","categories":["شروط الحج"]},{"id":8467,"question":"أولى رسائل هذه الحلقة سماحة الشيخ رسالة تتحدث عن موضوع من حجت بدون رضا زوجها، باعثة الرسالة هي أختنا: صالحة مغضب بخيت ، من ينبع البحر تقول: أطلب إفادتكم في الآتي: لقد طلبت من زوجي أداء فريضة الحج معه ولكن بيني وبينه سوء تفاهم، ولم أذهب معه وبعد عام أديت فريضة الحج والعمرة مع إخواني من غير رضاه، ويقال: الزوج إذا كان زعلان عليها لا ترضى الملائكة إلا برضا زوجها، والرجاء إفادتي هل حجي صحيح من غير رضاه أم لا، ولكم الشكر؟","title":"حكم حج المرأة بدون رضا زوجها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالحج الفريضة لا يشترط فيه رضا الزوج، لكن إذا تيسر رضاه فهو أحسن وأطيب وإلا فلا يشترط، وحجك صحيح والحمد لله، وهذا شيء لازم لك ولغيرك من المكلفين، كل من استطاع الحج وجب عليه الحج، فالزوجة إذا لم يأذن زوجها لها في الحج الفريضة يسقط حقه وعليها أن تحج، كما أن عليها أن تصوم رمضان ولو لم يرض، وإنما هذا في النافلة ليس لها حج النافلة ولا صوم النافلة وهو شاهد إلا بإذنه، فأما حج الفريضة فلها أن تحج بغير إذنه إذا لم يسمح لها؛ لأن الله أوجب على المسلمين حج الفرض في قوله سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] رزق الله الجميع التوفيق والهداية. نعم.\nالمقدم: اللهم آمين جزاكم الله خيراً، سماحة الشيخ أختنا لم تذكر رضا الله سبحانه وتعالى وإنما ذكرت رضا الملائكة لعل لهذا شيء من التصحيح شيخ عبد العزيز؟\nالشيخ: هذا جاء في الحديث عن النبي ﷺ إذا بات الرجل وهو غضبان على زوجته كان الذي في السماء ساخطاً عليها حتى يرضى عنها وفي اللفظ الآخر: لعنتها الملائكة حتى تصبح فالواجب على المرأة أن تطيع زوجها في المعروف إذا دعاها إلى فراشه ولا تغضبه إلا من علة، فإذا أغضبته وبات وهو غضبان عليها هذا فيه خطر عليها من غضب الله وغضب الملائكة جميعاً، فينبغي للمرأة أن تحذر هذا وأن تجتهد في طاعة زوجها، والتماس رضاه في المعروف لا في المعاصي، إلا أن تكون هناك علة كأن تكون مريضة مرضاً لا يمكنها من تمكينه من حاجته فهي معذورة، أو كان قصر في حقها ولم يقم بواجبها فلها المطالبة بحقها فإذا أدى حقها وجب عليها السمع والطاعة في أداء حقه.\nوالعمرة مثل الحج مثلما تقدم العمرة مثل الحج؛ لأنها فريضة على الصحيح فإذا لم يسمح لها بالعمرة فلها أن تؤدي العمرة بغير إذنه، وهي مرة في العمر كالحج، الحج مرة في العمر والعمرة مرة في العمر، والباقي نافلة. نعم.","link":"https://binbaz.org.sa/fatwas/6478/حكم-حج-المراة-بدون-رضا-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_124/12401.mp3","categories":["شروط الحج"]},{"id":8485,"question":"المدان للبنوك هل عليه أن يحج أيضاً؟","title":"حكم الحج على المديون","answer":"الجواب: ما يلزمه الحج؛ لأن الله يقول: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] وفي الحديث يقول ﷺ: بني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمداً رسول الله، وإقام الصلاة وإيتاء الزكاة وصوم رمضان وحج البيت وفي حديث جبرائيل قال لـ: لمن استطاع إليه سبيلاً.\nفالمقصود أن الحج لا يجب إلا مع الاستطاعة، فإذا كان مديناً يبدأ بالدين وإن حج أجزأه إن حج وهو عليه الدين، أجزأه الحج، لكن الواجب عليه أن يبدأ بالدين قبل الحج، إلا إذا سمح أهل الدين وعفوا عن حجه ولو أخر دينهم لا بأس، إذا كان الدين محدوداً لأناس معينين وسمحوا فلا بأس، وإلا فالواجب أن يبدأ بالدين، فإن حج ولم يقض الدين فلا شيء عليه، حجه صحيح أو كان عنده ما يؤدي منه كان عنده مال ليس عليه خطر إذا حج ليس عليه خطر عنده مال، فإنه يلزمه الحج، إذا كان عنده قدرة واستطاعة لكنه تساهل حجه صحيح ويلزمه الحج، ويلزمه أيضاً أن يبادر بقضاء الدين إذا أمكنه ذلك، أما إذا كانوا غائبين أو لم يعرفهم أو ما أشبه ذلك مما يمنعه من قضاء الدين فيحج ومتى أدركهم ومتى قدر عليهم أعطاهم حقوقهم. نعم.","link":"https://binbaz.org.sa/fatwas/6544/حكم-الحج-على-المديون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12512.mp3","categories":["شروط الحج"]},{"id":8621,"question":"مستمعة من المغرب لم تذكر اسمها بل قالت: مستمعة من المغرب الشقيق السلام عليكم ورحمة الله وبركاته، لقد أعجبنا ببرنامجكم نور على الدرب، وأرجو من العلي القدير أن يعمم هذا البرنامج على جميع الأمة، إذ أنا استفدنا منه كثيراً، ونرجو أن يستفيد الآخرون في دينهم ودنياهم، وأردنا أن نكون من المراسلين لهذا البرنامج.أسأل السؤال الأول لو تكرمتم: أديت فريضة الحج بدون محرم، ما حكم حجي؟","title":"حكم من حجت بغير محرم","answer":"الجواب: الحج صحيح والحمد لله، وقد سقطت به الفريضة، ونسأل الله أن يتقبله منك، ولكنك أخطأت في الحج بغير محرم فعليك التوبة إلى الله من ذلك والاستغفار والندم، وأن لا تحجي مستقبلاً إلا بمحرم؛ لقول النبي الكريم ﷺ: لا تسافر امرأة إلا مع ذي محرم متفق على صحته، فالرسول ﷺ قال: لا تسافر امرأة إلا مع ذي محرم فعليك وعلى غيرك من المسلمات الامتثال، وأن لا تسافر امرأة إلا مع ذي محرم، والمحرم معروف: زوجها أو أبوها أو أخوها أو نحوهم ممن تحرم عليه على التأبيد بسبب قرابته منها، أو بسبب مصاهرة أو رضاع. وأما الحج فقد حصل به المقصود وأديت الفريضة والحمد لله.\nالمقدم: تقول: إنها استغلت وجودها في المملكة وهي تعمل هنا فحجت سماحة الشيخ، فكأنها تشرح السبب؟\nالشيخ: هذا لا بأس، المقصود أن الحج صحيح، والمستقبل ليس لها الحج إلا بمحرم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6753/حكم-من-حجت-بغير-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12910.mp3","categories":["شروط الحج"]},{"id":8623,"question":"له سؤال ثان الأخ يوسف عمر، في هذه الرسالة يقول فيه: هل يأثم من لم يتمكن من أداء فريضة الحج وهو مستطيع؛ لأن السلطات المختصة رفضت منحه تأشيرة خروج إلى الديار المقدسة بحجة أنه لم يبلغ الأربعين عاماً رغم أن فريضة الحج واجبة على كل مستطيع، أفيدونا أفادكم الله؟","title":"حكم الحج على من له القدرة عليه ومنعته الدولة","answer":"الجواب: يجب على المسلم إذا استطاع الحج بنفسه وماله أن يبادر إلى الحج ولو قبل الأربعين، من حين يبلغ الحلم ويستطيع الذهاب إلى البلاد المقدسة يلزمه الحج؛ لأن الله سبحانه يقول: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] والمعنى: لله واجب على الناس أو فرض على الناس، ويقول النبي ﷺ: بني الإسلام على خمس -يعني: على خمس دعائم- شهادة أن لا إله إلا الله، وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت وفي حديث عمر  قال ﷺ لما سأله جبرائيل عن الإسلام قال: الإسلام: أن تشهد أن لا إله إلا الله، وأن محمداً رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت إن استطعت إليه سبيلاً فمتى استطاع السبيل إليه وهو بالغ وجب عليه السفر إلى الحج، وهكذا المرأة إذا استطاعت السبيل إليه وعندها محرم وهي بالغة وجب عليها السعي للحج.\nلكن إذا كان ممنوع، إذا كان ممنوعاً من جهة السلطة الحاكمة فهو معذور حتى تأذن له السلطة حتى يتمكن؛ لأن الله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول : لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ويقول النبي ﷺ: إذا أمرتكم بأمر فأتوا منه ما استطعتم وهذا من تيسير الله  ولطفه؛ لأنه نفى الحرج عمن لم يستطع.\nوالواجب على الحكومات الإسلامية أن تنظر في هذا الأمر وأن لا تشدد على الناس، وأن تفسح لهم المجال قبل الأربعين، فمن للإنسان أنه يعيش حتى يكمل الأربعين، من يضمن له أنه يبقى، فالواجب على الحكومات الإسلامية أن تترك هذا القرار وهذا القانون، والواجب عليها أن تعين على الخير، فالله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] والحج من البر ومن التقوى، فالواجب على جميع الدول الإسلامية أن تفسح لشعوبها المسلمين أن يحجوا إذا استطاعوا قبل الأربعين، متى بلغ الحلم واستطاع يفسح له في الحج على طريقة منظمة يحصل بها المقصود من غير تأخير للحج. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6764/حكم-الحج-على-من-له-القدرة-عليه-ومنعته-الدولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21105.mp3","categories":["شروط الحج"]},{"id":8632,"question":"له سؤال ثان الأخ يوسف عمر، في هذه الرسالة يقول فيه: هل يأثم من لم يتمكن من أداء فريضة الحج وهو مستطيع؛ لأن السلطات المختصة رفضت منحه تأشيرة خروج إلى الديار المقدسة بحجة أنه لم يبلغ الأربعين عاماً رغم أن فريضة الحج واجبة على كل مستطيع، أفيدونا أفادكم الله؟","title":"حكم الحج على من له القدرة عليه ومنعته الدولة","answer":"الجواب: يجب على المسلم إذا استطاع الحج بنفسه وماله أن يبادر إلى الحج ولو قبل الأربعين، من حين يبلغ الحلم ويستطيع الذهاب إلى البلاد المقدسة يلزمه الحج؛ لأن الله سبحانه يقول: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] والمعنى: لله واجب على الناس أو فرض على الناس، ويقول النبي ﷺ: بني الإسلام على خمس -يعني: على خمس دعائم- شهادة أن لا إله إلا الله، وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت وفي حديث عمر  قال ﷺ لما سأله جبرائيل عن الإسلام قال: الإسلام: أن تشهد أن لا إله إلا الله، وأن محمداً رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت إن استطعت إليه سبيلاً فمتى استطاع السبيل إليه وهو بالغ وجب عليه السفر إلى الحج، وهكذا المرأة إذا استطاعت السبيل إليه وعندها محرم وهي بالغة وجب عليها السعي للحج.\nلكن إذا كان ممنوع، إذا كان ممنوعاً من جهة السلطة الحاكمة فهو معذور حتى تأذن له السلطة حتى يتمكن؛ لأن الله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول : لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ويقول النبي ﷺ: إذا أمرتكم بأمر فأتوا منه ما استطعتم وهذا من تيسير الله  ولطفه؛ لأنه نفى الحرج عمن لم يستطع.\nوالواجب على الحكومات الإسلامية أن تنظر في هذا الأمر وأن لا تشدد على الناس، وأن تفسح لهم المجال قبل الأربعين، فمن للإنسان أنه يعيش حتى يكمل الأربعين، من يضمن له أنه يبقى، فالواجب على الحكومات الإسلامية أن تترك هذا القرار وهذا القانون، والواجب عليها أن تعين على الخير، فالله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] والحج من البر ومن التقوى، فالواجب على جميع الدول الإسلامية أن تفسح لشعوبها المسلمين أن يحجوا إذا استطاعوا قبل الأربعين، متى بلغ الحلم واستطاع يفسح له في الحج على طريقة منظمة يحصل بها المقصود من غير تأخير للحج. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6764/حكم-الحج-على-من-له-القدرة-عليه-ومنعته-الدولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21105.mp3","categories":["شروط الحج"]},{"id":8818,"question":"فهنا سؤال يسأله أحد الإخوة المستمعين ويقول: حدثونا عن حكم امرأة حجت بدون محرم لكنها مع مجموعة من النساء؟","title":"حكم حج المرأة مع مجموعة من النساء بدون محرم","answer":"فعلينا أن نسمع ونطيع لما وجهنا إليه عليه الصلاة والسلام، وقد قال عليه الصلاة والسلام: لا تسافر المرأة إلا مع ذي محرم ولو كان معها نساء، لكن تصح الحجة، حجها صحيح وعليها التوبة والاستغفار. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6973/حكم-حج-المراة-مع-مجموعة-من-النساء-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_163/163002.mp3","categories":["شروط الحج"]},{"id":8819,"question":"أيضًا عن شخص يريد الحج لكن نفقة حجه كانت من سؤال الناس؟","title":"حكم من يسأل الناس مالًا ليحج به","answer":"الجواب: نعم، حجه صحيح، حجه صحيح، أما سؤاله الناس ففيه التفصيل: إن كان سأل الناس عن حاجة وعن مسكنة وصدق، فلا حرج عليه والحمد لله.\nأما إن كان سألهم تكثرًا وعن غير صدق فهو آثم وعليه التوبة إلى الله من ذلك، وقد صح عن رسول الله عليه الصلاة والسلام أنه سأله قبيصة أن يساعده، فقال له ﷺ: اجلس حتى تأتينا صدقة بني فلان فنأمر لك بها، ثم قال: يا قبيصة! إن المسألة لا تحل إلا لأحد ثلاثة: رجل تحمل حمالة فحلت له المسألة حتى يصيبها ثم يمسك، ورجل أصابته جائحة اجتاحت ماله فحلت له المسألة حتى يصيب قوامًا من عيش -أو قال: سدادًا من عيش- ورجل أصابته فاقة حتى يقوم ثلاثة من ذوي الحجا من قومه يقولون: لقد أصابت فلان فاقة، فحلت له المسألة حتى يصيب قوامًا من عيش -أو قال: سدادًا من عيش-قال: وما سوى ذلك -يا قبيصة- سحت يأكلها صاحبها سحتًا فهذا يدل على أن المسألة إذا كانت بغير الأوجه الثلاثة تكون محرمة، ومن هذا ما ثبت عنه ﷺ في صحيح مسلم أنه قال عليه الصلاة والسلام: من سأل الناس أموالهم تكثرًا فإنما يسأل الجمر فليستقل أو ليستكثر وهذا وعيد عظيم فالإنسان إذا كانت له واحدة من هذه المسائل فلا بأس أن يسأل: إما أن يكون تحمل حمالة، وإما أن يكون أصابته جائحة، وإما أن يكون أصابته فاقة، فالحمالة معناها: أنه تحمل دينًا لحاجة أولاده وعائلته أو تحملها للإصلاح بين الناس فإنه يعطى من الزكاة ما يسد هذه الحمالة وله أن يسأل إذا كان عاجزًا حتى تسد هذه الحمالة.\nوظاهر النص ولو لم يكن عاجزًا، إذا كانت الحمالة في مصلحة المسلمين لا لحاجته هو، أما إذا كان لحاجته وأغناه الله فلا حاجة إلى أن يسأل، لكن إذا كان تحمل حمالة للمسلمين لمصلحة المسلمين، فهذا يعطى ولو؛ لأن قبيصة تحمل حمالة للإصلاح، فإذا تحمل إنسان مالًا ليصلح بين قبيلتين أو بين أهل قريتين أو نحو ذلك فهو مشكور وقد عمل عملًا طيبًا، فينبغي أن يساعد من الزكاة حتى لا يكسل الكبار والرؤساء والأعيان عن الإصلاح، فيعطى من الزكاة تلك الحمالة شكرًا له على عمله الطيب، وتشجيعًا له ولأمثاله على العودة إلى مثل ذلك من الزكاة أو من بيت المال.\nالثاني: من أصابته جائحة اجتاحت ماله مثل سيل أو حريق أو ما أشبه ذلك مما يزول معه المال، فهذا يعطى من الزكاة أو غيرها ما يحصل به السداد، يعني: سداد حاله، قوام حاله، السداد -بالكسر-والقوام ما يسد الحاجة، يعني: يعطى من بيت المال أو من الزكاة ما يسد الحاجة حتى يلتمس له عملًا.. حتى يلتمس له سببًا يقوم بحاله.\nالثالث: الذي كان في خير ثم أصابته فاقة، يعني: أصابته حاجة شديدة إما لكساد البضاعة التي يتسبب بها، أو لأسباب أخرى حصلت له فاقة غير الجائحة، أصابته فاقة بأسباب كثيرة إما رخص الأسعار، وإما مرضه وعجزه عن العمل، وإما غير ذلك، فهذا يعطى سدادًا من عيش، يعطى من الزكاة وغيرها ما يقوم بحاله ويسد حاجته شهريًا أو سنويًا فيستغني بذلك عن السؤال. نعم.\nالمقدم:بارك الله فيكم، إذًا: الشروع في الحج والمرء ليس لديه نفقته هذا غير جائز؟\nالشيخ: لا يجوز له، إلا إذا تبرع له أحد بأن قال: تحج معنا يا فلان أو نعطيك النفقة فلا بأس، لكن لا يحج بسؤال الناس، الله جل وعلا إنما أوجب الحج على المستطيع، فالذي إنما يحج بسؤال الناس لا يسأل الناس، فإذا كان عنده ما يسد حاجتة فالحمد لله لا يسأل الناس، والحج ليس بلازم حتى يستطيع، لكن لو حج بمال حصل عن سؤال مذموم أو من طريق حرام كالسرقة أو الخيانة أو الربا أو ما أشبه ذلك صح الحج؛ لأن أركان الحج وواجباته كلها بدنية، وهو عليه التوبة إلى الله مما فعل، ورد الأموال إلى أهلها إن كانت عن سرقة أو نحوها. نعم.","link":"https://binbaz.org.sa/fatwas/6974/حكم-من-يسال-الناس-مالا-ليحج-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_163/16303.mp3","categories":["شروط الحج"]},{"id":8923,"question":"أخونا يقول: لقد حججت وأنا طالب في الجامعة وأخذت مالاً من والدي لمصاريف الحج وذلك لعدم استطاعتي توفير المال بنفسي، ولكن والدي يعمل آنذاك في أعمال محرمة وأرباحه من تلك الأعمال المحرمة، فهل حجي صحيح أو أنكم ترون علي أن أعيد تأدية الفريضة مرة أخرى؟","title":"حكم الحج من المال الحرام","answer":"الجواب: الحج صحيح ولا يضره كون المال فيه شبهة أو ليس بحلال؛ لأن أعمال الحج كلها بدنية، أعمال الحج كلها بدنية وإن كانت النفقات الخبيثة تسبب شرًا كثيرًا، وقد تكون سببًا لعدم قبول الحج وقد تكون أيضاً سبباً لقلة الحسنات وكثرة السيئات، لكن بكل حال فالحج صحيح وإن كان أجره ليس مثل أجر من حج من مال حلال لكن الحج صحيح ويجزئ وليس عليك حج بعد ذلك؛ لأن الأعمال بدنية؛ طواف، سعي، وقوف بعرفات، رمي الجمار كلها بدنية ما فيها إلا مجرد الهدي، هدي التمتع، وهذا الهدي إذا أنفقته من مال أخذته من أبيك وأنت تعلم حال أبيك فالأصل الحل وأنت لا تعلم أن هذا المال حرام بعينه حتى تقول: إنك اشتريت بمال حرام، فالأصل إجزاء الذبيحة التي ذبحتها والأصل سلامة المال حتى تعلم عين المال أنه مغصوب من فلان، أو أنه حصل عن ربا معين، يعني: حتى تتيقن أنه حرام، فما دمت لا تتيقن أنه حرام هذا المال المعين فالأصل حل الذبيحة وأنها أدت الواجب والحمد لله، أما إذا كنت تتيقن أن الذبيحة اشتريتها بمال حرام فينبغي أن تشتري بدلها الآن وتذبحها عن حجك السابق، والحمد لله.نعم.\nالمقدم: بارك الله فيكم، إذاً: الحج كله ليس عليه إعادة فيه؟\nالشيخ: نعم.. نعم، أبداً.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7080/حكم-الحج-من-المال-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_142/14204.mp3","categories":["شروط الحج"]},{"id":8944,"question":"إحدى الأخوات المتدينات -كما وصفت نفسها- بعثت بمجموعة من الأسئلة في سؤال لها الأول يقول: إذا لم تجد المرأة محرمًا ليسافر بها إلى الحج هل تسقط عنها الفريضة، وإذا كان هناك محرم غير أنه أبى السفر معها فما الحكم؟","title":"حكم المرأة إذا لم تستطع الحج لعدم وجود المحرم","answer":"الجواب: الصحيح أنه لا شيء عليها لكن يكون الأمر معلقًا فإن تيسر محرم قبل أن تموت وهي قادرة حجت، وإن لم يتيسر فلا شيء عليها ولا حرج، والحمد لله؛ لأن الرسول ﷺ نهى أن تسافر إلا مع ذي محرم، فهي معذورة شرعًا فلو ماتت ولم يتيسر المحرم فلا شيء عليها، والحمد لله.\nالمقدم: بارك الله فيكم، هل من كلمة للمحارم حول هذا الموضوع شيخ عبد العزيز؟\nالشيخ: نعم، نوصي أخواتي المسلمات نوصيهن بتقوى الله وأن يحذرن من السفر إلا بمحرم، ونوصي المحارم أن يتقوا الله وأن يحسنوا في محارمهم إذا احتجن إليهم لحج أو لأمر آخر مما أباحه الله أن يساعدوا وأن لا يمتنعوا فالله جل وعلا يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] والنبي ﷺ يقول: من كان في حاجة أخيه كان الله في حاجته ويقول ﷺ: والله في عون العبد ما كان العبد في عون أخيه فالوصية للنساء أن لا يتساهلن في هذا الأمر، وأن لا يخرجن مع النساء ولا مع غير النساء إلا بمحرم في الأسفار لا للحج ولا لغير الحج.\nوالوصية للرجال أن يتقوا الله وأن يحسنوا في محارمهم إذا دعت الحاجة إلى سفر المرأة إلى الحج أو إلى أمر مهم شرعًا فإنهم يشرع لهم أن يساعدوا وأن يسافروا معهم لقضاء هذه المهمة التي ليس فيها إلا الخير. نعم.\nالمقدم: كأني أفهم من رسالة هذه الأخت المستمعة أن بعض الرجال يأنفون من خدمة النساء سماحة الشيخ، هل من كلمة لو تكرمتم؟\nالشيخ: ليس في هذا خدمة، وإنما في هذا مساعدة على الخير وإحسان وأداء لواجب وهو الحج هو يساعدها في أداء الواجب، فإذا سافر معها إلى الحج فإنما هو محسن وإذا خدم محرمه في سفره معها فهذه خدمة شريفة يؤجر عليها والحمد لله، وإذا خدمها في صلة رحمها في نقلها للطبيب بالمجيء إليها بالدواء، في مساعدتها إذا كانت فقيرة كل هذا خدمة طيبة مشروعة، من كان في حاجة أخيه كان الله في حاجته وكون المسلم يخدم أخاه في الله أو أخته في الله أو محرمه هذا شرف له، وأجر له عظيم ليس فيه نقص.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7102/حكم-المراة-اذا-لم-تستطع-الحج-لعدم-وجود-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_172/17206.mp3","categories":["شروط الحج"]},{"id":9003,"question":"السؤال الثاني في رسالة الأخت: خمرية سلمان بني من العراق تقول فيه: أنوي الذهاب إلى بيت الله الحرام لأداء فريضة الحج، وأملك مبلغاً من المال قدره ألف دينار، فما هو المبلغ المخصص لكي أؤدي فريضة الحج؟ أفيدونا أفادكم الله.","title":"بيان القول في مقدار النفقة في الحج","answer":"الجواب: ليس للحج مؤونة مخصصة، بل حسب الطاقة، يقول الله : وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] والنبي ﷺ يقول لما سئل عن الإسلام قال: الإسلام: أن تشهد أن لا إله إلا الله، وأن محمداً رسول الله، وتقيم الصلاة وتؤتي الزكاة، وتصوم رمضان وتحج البيت إن استطعت إليه سبيلاً فإذا استطاع الرجل أو المرأة المئونة فعليهم الحج، والمئونة تختلف في كل زمان ومكان تختلف، فالرحيل من العراق إلى مكة له حال، والرحيل من أمريكا إلى مكة له حال، والرحيل من المغرب إلى مكة له حال، فعلى كل حال على المؤمن الحج إذا استطاع، إذا كان عنده من النفقة ما يكفي لذهابه وإيابه، ولنفقة من يبقى بعده في البيت من العوائل إذا استطاع ذلك حج، فإن لم يستطع فلا شيء عليه، وليس لهذا حد محدود، بل المطلوب القدرة على نفقة السيارة، أجرة السيارة أجرة الطائرة، نفقة الطريق النفقة في مكة، النفقة في الرجوع إلى غير هذا من توابع الحج، فإذا استطاع الرجل أو المرأة هذه النفقة فعليهما الحج، وإن لم يستطيعا فلا حج عليهما، والحمد لله.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7164/بيان-القول-في-مقدار-النفقة-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_223/22307.mp3","categories":["شروط الحج"]},{"id":9004,"question":"السؤال الثاني في رسالة الأخت: خمرية سلمان بني من العراق تقول فيه: أنوي الذهاب إلى بيت الله الحرام لأداء فريضة الحج، وأملك مبلغاً من المال قدره ألف دينار، فما هو المبلغ المخصص لكي أؤدي فريضة الحج؟ أفيدونا أفادكم الله.","title":"بيان القول في مقدار النفقة في الحج","answer":"الجواب: ليس للحج مؤونة مخصصة، بل حسب الطاقة، يقول الله : وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] والنبي ﷺ يقول لما سئل عن الإسلام قال: الإسلام: أن تشهد أن لا إله إلا الله، وأن محمداً رسول الله، وتقيم الصلاة وتؤتي الزكاة، وتصوم رمضان وتحج البيت إن استطعت إليه سبيلاً فإذا استطاع الرجل أو المرأة المئونة فعليهم الحج، والمئونة تختلف في كل زمان ومكان تختلف، فالرحيل من العراق إلى مكة له حال، والرحيل من أمريكا إلى مكة له حال، والرحيل من المغرب إلى مكة له حال، فعلى كل حال على المؤمن الحج إذا استطاع، إذا كان عنده من النفقة ما يكفي لذهابه وإيابه، ولنفقة من يبقى بعده في البيت من العوائل إذا استطاع ذلك حج، فإن لم يستطع فلا شيء عليه، وليس لهذا حد محدود، بل المطلوب القدرة على نفقة السيارة، أجرة السيارة أجرة الطائرة، نفقة الطريق النفقة في مكة، النفقة في الرجوع إلى غير هذا من توابع الحج، فإذا استطاع الرجل أو المرأة هذه النفقة فعليهما الحج، وإن لم يستطيعا فلا حج عليهما، والحمد لله.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7164/بيان-القول-في-مقدار-النفقة-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_223/22307.mp3","categories":["شروط الحج"]},{"id":9107,"question":"وهذه رسالة وصلت إلى البرنامج من المستمعة الحاجة: عباسية بنت محمد عبدالرحمن من العراق -الموصل- تقول فيها: قدمت للحج بصحبة عدد من النساء وليس لي محرم وقد تجاوز عمري الخمسين عاماً، فهل يعتبر حجي صحيحاً أفيدونا أفادكم الله؟","title":"حكم حج المرأة مع نساء بدون محرم","answer":"الجواب: لا يجوز للمسلمة أن تحج بدون محرم، النبي ﷺ قال: لا تسافر امرأة إلا مع ذي محرم وقد ذهب بعض العلماء إلى جواز الحج مع ثقات النساء بدون محرم ولكنه قول مرجوح، والصواب: ما قاله النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم لكن لو حجت مع النساء صح حجها، وعليها التوبة إلى الله؛ لأنها أخطأت وأثمت فعليها التوبة إلى الله والندم وأن لا تعود إلى مثل هذا وحجها صحيح إن شاء الله؛ لأنها.. أدت مناسك الحج، فصح مع الإثم في مخالفتها السنة، في حجها بدون محرم، والله ولي التوفيق، وله سبحانه وتعالى الحكمة البالغة وعليها التوبة من ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7271/حكم-حج-المراة-مع-نساء-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22713.mp3","categories":["شروط الحج"]},{"id":9326,"question":"يسأل أيضاً ويقول: هل يصلح له الحج من أموال ابنه أم لا؟","title":"حكم حج الوالد من مال ابنه","answer":"الجواب: نعم، يصلح له الحج لكن لا يلزمه إلا إذا استطاع بنفسه، إذا كان عنده مال بنفسه، أما إذا حج من مال ابنه فحجه صحيح.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7498/حكم-حج-الوالد-من-مال-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23713.mp3","categories":["شروط الحج"]},{"id":9906,"question":"تقول هذه السائلة تعودنا في كل رمضان أداء العمرة، ولكن والدي لا يذهب معنا دائمًا ويسمح لوالدتي بالذهاب، هل عليها إثم إذا تركته لوحده وهي لا تعلم ما إذا كان راضيًا بقلبه، أم لا؟ وجزاكم الله خيرًا.","title":"حكم استئذان المرأة زوجها في العمرة والحج","answer":"الجواب: متى سمح لها والحمد لله يكفي، متى سمح لها بالعمرة والحج فلا حرج عليها، والقلوب إلى الله ، فمتى سمح لها فإنها تحج وتعتمر حج النافلة، عمرة النافلة، أما الفريضة فيجب عليها الحج ولو ما سمح إذا وجد لها المحرم يجب عليها أن تحج، أما النافلة فلا حرج إن سمح لها حجت وإلا فلا تحج، وإذا رأت المصلحة في خدمته قدمت مصلحته إذا رأت المصلحة في خدمته وأنه محتاج إليها فالأفضل أن تخدمه لأنه قد يسمح لها وهو غير راضي فإذا جلست عنده تخدمه وتراعي مصالحه فهو أفضل. نعم.","link":"https://binbaz.org.sa/fatwas/8074/حكم-استىذان-المراة-زوجها-في-العمرة-والحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27318.mp3","categories":["شروط الحج","قضايا المرأة"]},{"id":10109,"question":"إذا حجت المرأة دون إذن زوجها مع محرم لها وهو يمنعها من الحج، فما حكم حجها؟","title":"حكم حج المرأة بدون إذن زوجها","answer":"","link":"https://binbaz.org.sa/fatwas/8280/حكم-حج-المراة-بدون-اذن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27705.mp3","categories":["شروط الحج","قضايا المرأة"]},{"id":10113,"question":"يقول: حجيت ولما عدت من الحج غضب الوالد علي؛ لأني حجيت بدون إذنه، فما حكم حجي مع العلم أنها أول حجة أحجها؟","title":"حكم استئذان الوالد في الذهاب للحج","answer":"الجواب: حج الفريضة ما يحتاج إذن، واجب عليك أن تحج ولو لم يأذن لك أبوك، ولو لم يرض أبوك ولا أمك، يقول النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق، لكن لو أخبرته أريد أحج بالكلام الطيب يكون هذا من الآداب الشرعية، تقول: يا والدي! أنا حج الفريضة لازم وأبى أحج، من باب أخذ خاطره، ومن باب المجاملة والكلام الطيب هذا حسن، فإذا أبى لا يلزمك طاعته بل يلزمك أن تحج، لكن كلامك معه بالكلام الطيب والاستئذان وإخباره بالواقع هذا يكون حسن ويكون طيبًا، ومن أسباب طيب القلوب، لكن لو منع لا يلزمك أن تطيعه، بل يلزمك أن تحج ولو أبى.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8284/حكم-استىذان-الوالد-في-الذهاب-للحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27707.mp3","categories":["شروط الحج"]},{"id":10606,"question":"المستمعة (ن. س. ك) سودانية مقيمة في المملكة تقول: حج والدي من مال، لكن هذا المال يشترك معه إخوانه في الإرث، وهم غير مسامحين له بذلك، هل حجه صحيح؟ أم ماذا يجب عليه؟","title":"حكم من حج بمال حرام","answer":"الجواب: حجه صحيح، وعليه التوبة مما فعل واستسماح إخوته وإعطاؤهم حقوقهم، وحجه صحيح وعليه التوبة إلى الله؛ لأن حل النفقة ليس شرطاً في صحة الحج، الحج أعمال بدنية، فإذا أدى أعمال الحج على الوجه الذي شرعه الله صح حجه، ولكنه يأثم إذا كانت النفقة محرمة أو فيها شيء محرم يأثم وينقص ثواب الحج، ولكن لا يبطل الحج، بل حجه مجزئ وصحيح لكن عليه إثم تعاطي ما حرم الله من مال إخوته، فعليه أن يستسمحهم وأن يتوب إلى الله من ذلك؛ حتى ينجبر حجه بالتوبة.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8779/حكم-من-حج-بمال-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32606.mp3","categories":["شروط الحج"]},{"id":10680,"question":"هل يجوز للمرأة أن تذهب مع زوج ابنتها للحج أو العمرة، أو زيارة المسجد النبوي الشريف؟","title":"حكم سفر المرأة مع زوج ابنتها للحج والعمرة","answer":"الجواب: زوج البنت محرم، زوج بنتها محرم لها، فإذا ذهبت معه سافرت معه للحج أو العمرة أو لأي سفر مباح فلا بأس بذلك؛ لأنه محرم، زوج بنتها، وزوج أمها، وزوج جدتها، كلهم محارم، وزوج بنت ابنها، وبنت بنتها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8869/حكم-سفر-المراة-مع-زوج-ابنتها-للحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33019.mp3","categories":["شروط الحج"]},{"id":10686,"question":"هل يجوز للمرأة أن تذهب مع زوج ابنتها للحج أو العمرة، أو زيارة المسجد النبوي الشريف؟","title":"حكم سفر المرأة مع زوج ابنتها للحج والعمرة","answer":"الجواب: زوج البنت محرم، زوج بنتها محرم لها، فإذا ذهبت معه سافرت معه للحج أو العمرة أو لأي سفر مباح فلا بأس بذلك؛ لأنه محرم، زوج بنتها، وزوج أمها، وزوج جدتها، كلهم محارم، وزوج بنت ابنها، وبنت بنتها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8869/حكم-سفر-المراة-مع-زوج-ابنتها-للحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33019.mp3","categories":["شروط الحج"]},{"id":12053,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المستمعة (هـ. أ. س) أختنا تقول: زوجي يريد أن يحج بأبي، فهل له ذلك؟ لأن والدي حاله ميسور، كما تقول، جزاكم الله خيرًا.","title":"حكم من حج على نفقة غيره","answer":"الجواب:  لا حرج في ذلك إذا رافق الشخص الملي على أن يحج مع غيره على نفقة الغير؛ فلا بأس، ولكن إذا حج من نفقته وماله؛ يكون أكمل وأطيب، إلا إذا رأى أن الحج مع الغير على نفقة غيره لها مصالح دينية، تفقه في الدين وتعلم، هذا فيه مصلحة كبرى، ولو على حساب غيره، لا بأس طيب حتى يستفيد من العلم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10238/حكم-من-حج-على-نفقة-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43402.mp3","categories":["شروط الحج"]},{"id":12403,"question":"يقول: والدتي تحتاج إلى مال تحج به، وعندها مال، هل يلزمني نفقة حجها، أو يلزم والدتي؟","title":"حكم لزوم نفقة حج الوالدة على الولد وعندها مال","answer":"الجواب:  لا تلزمك النفقة ما دام عندها مال، فعليها أن تنفق من مالها، هذا إذا كان حجها فريضة، أما إذا كان حجها نافلة؛ فليس عليها شيء، الحج مرة في العمر، كما قاله النبي ﷺ الحج مرة، فما زاد؛ فهو تطوع، فإذا كانت قد حجت؛ فالحمد لله، إن أرادت تطوعًا؛ تنفق من مالها، وأنت تساعدها، وتذهب معها إلى مكة، وإن أنفقت من مالك برًا بها، وإحسانًا إليها، ورغبة في تشجيعها على الخير؛ فأنت مأجور، فإذا كنت تستطيع؛ فالأحسن أنك لا تحاسبها، تنفق من مالك، وهذه نعمة من الله، عليك أن تنفق عليها، وأن تحسن إليها، فأبشر بالخير، ولا تحاسبها، ولا تناقشها في هذا إذا كنت تستطيع، أنفق وأحسن وأبشر بالخير، وساعدها على الحج، ولو نافلة، وأنت على خير عظيم، وأجر كبير، لكن لا يلزمك، ما دام عندها مال لا يلزمك، لكن من برك لها، وإحسانك إليها، ومن مراعاة خاطرها حتى لا يكون في خاطرها شيء عليك أن تنفق من مالك، وأن تحسن إليها، وأن تفرح بأن تنفق عليها، وأن تحج بها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10608/حكم-لزوم-نفقة-حج-الوالدة-على-الولد-وعندها-مال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45508.mp3","categories":["شروط الحج"]},{"id":13811,"question":"السائل الذي رمز لاسمه بـ (أ. ع. م) مصري ويعمل بمدينة الرياض، يقول: بأنني قد عزمت ونويت أن أقضي فريضة حج هذا العام إن شاء الله، ولكن شقيقي له عندي مبلغ من المال وأنا لا أستطيع أن أعطيه هذا المبلغ في هذه الفترة نظراً لظروفي، فهل يسقط عني الحج؟ وبماذا توجهونني؟","title":"هل يقدم الدين على فريضة الحج؟","answer":"الجواب: نوجهك بأن تدفع إليه ما تيسر لك من المال وتقدمه على الحج؛ لأن هذا دين لازم والحج ما هو بلازم إلا مع الاستطاعة، فإذا كان الأمر هكذا تبدأ بالدين والحج يؤجل والحمد لله، إلا إذا كان صاحب الدين معروف وسمح لك فلا بأس، وإلا فالواجب أن تقدم الدين ولو أن الدين كثير تقدم يخفف عنك، النفقة التي تنفقها في الحج ألف ريال أو أقل أو أكثر تعطيها هذا الدين والحمد لله، والحج أنت قد أمهلك الله ويسر أمرك، قال: مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا[آل عمران:97]، وأنت غير مستطيع. نعم.","link":"https://binbaz.org.sa/fatwas/12179/هل-يقدم-الدين-على-فريضة-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53623.mp3","categories":["شروط الحج"]},{"id":14696,"question":"والدتي نوت الحج، ولم يوجد لديها مال، فهل يجوز لها أن تأخذ من مال ولدها لتقوم بفريضة الحج؟مع العلم أن الوالد موجود.","title":"حكم الأخذ من مال الولد لأداء فريضة الحج","answer":"الجواب: إذا سلمها ابنها مالًا عن طيب نفس تحج به، أو سلمها أبوها أو أخوها فلا بأس بذلك، ولكن ليس عليها حج، ولا عمرة إذا كانت لا تستطيع من مالها؛ لأن الله سبحانه يقول: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97]. فإذا كانت عاجزة عن الحج، أو عن العمرة ليس عندها مال فليس عليها حج ولا عمرة، لكن إذا ساعدها أبوها أو أخوها أو ابنها أو خالها أو غيرهم ساعدوها في ذلك، فالحمد لله، لا بأس بذلك، والحج صحيح إذا أدته كما شرع الله، والعمرة كذلك، نعم.\nالمقدم: جزاكم الله خيرًا، الذي يساعدها سواء كان أدى الحج عن نفسه أو لم يؤده؟\nالشيخ: نعم، سواء أداه أو ما أداه، المساعدة بالمال لا بأس، ولو كان ما حج عن نفسه، إنما يمنع أن يحج عن غيره إذا كان يحج عن نفسه، يعني إذا باشر الحج بنفسه، أما إذا ساعده بالمال فلا بأس، ولو ما حج عن نفسه، وهكذا العمرة لا يعتمر عن غيره إلا إذا كان اعتمر عن نفسه، لكن إذا ساعده بالمال لبعض الناس حتى يحجوا ويعتمروا فلا بأس وهو مأجور؛ لأن الرسول ﷺ يقول: الله في عون العبد ما كان العبد في عون أخيه ويقول النبي ﷺ: من كان في حاجة أخيه كان الله في حاجته نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13207/حكم-الاخذ-من-مال-الولد-لاداء-فريضة-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62904.mp3","categories":["شروط الحج"]},{"id":14923,"question":"المستمع: (صالح . ب. م) من مكة المكرمة، بعث برسالة ضمنها عددًا من أسئلته، في أحد أسئلته يقول: لدي أخ بلغ من العمر أربعة عشر عامًا، هل عليه أن يؤدي فريضة الحج في هذا السن؟","title":"حكم الحج على من عمره أربع عشرة سنة","answer":"الجواب: إذا كان قد احتلم، يعني: أنزل المني في النوم، أو في اليقظة بسبب الشهوة؛ فهو بالغ، وإن كان لم يكمل الخمسة عشر سنة، أو أنبت الشعر الخشن حول الفرج -الشعرة- إذا كان قد أنبت الشعر فهو بالغ، فله أن يحج، ولو بهذا السن، أربعة عشر سنة.  أما إذا كان لم ينبت، ولم يحتلم؛ فإنه لا يلزمه الحج، حتى يبلغ خمسة عشر سنة، يعني: حتى يكمل خمسة عشر سنة، أو ينزل المني عن شهوة، أو ينبت، فإن الرجل إنما يبلغ بأحد هذه الثلاثة: إما بإكمال خمسة عشر سنة، أو بإنبات الشعرة حول الفرج، أو باحتلامه -بإنزاله المني-، سواء في النوم، أو في اليقظة، إذا أنزل المني عن شهوة بأن فكر فأنزل، أو لمس ذكره فأنزل، احتلم ليلًا، أو نهارًا، فأنزل؛ فإنه يكون بهذا قد بلغ الحلم، ولو كان ابن عشر سنين، أو إحدى عشر سنة، أو ثنتا عشر سنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13429/حكم-الحج-على-من-عمره-اربع-عشرة-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64010.mp3","categories":["شروط الحج"]},{"id":16161,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من بريدة، باعثتها إحدى الأخوات من هناك تقول: ممرضة في أم حزم، واسمها وفاء محمد محمد عبدالمجيد، أختنا لها جمع من الأسئلة، في أحدها تقول: أنا سيدة، عمري خمس وثلاثون سنة، وصلت المملكة لأول مرة، وعندما كنت في مصر، كنت أتمنى أن أحج وأعتمر، ولقد أديت العمرة في رمضان، ولله الحمد، وقد نظمت الجهة التي نعمل فيها رحلة إلى الحج مقابل مبلغًا من المال، وقد قمت بتسجيل، اسمي ودفعت المبلغ، لكن بعض الناس يقولون: هذا حرام، لا يجوز إلا ومعك محرم، أرجو أن توجهوني حول هذا الموضوع؟ جزاكم الله خيرًا.","title":"حكم سفر المرأة للحج بدون محرم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فنسأل الله -جل وعلا- أن يتقبل منا ومنك العمرة، وأن يسهل لك الحج على الطريقة التي يرضاها سبحانه. أيها الأخت في الله! السفر من المرأة للحج، أو غيره بدون محرم لا يجوز؛ وذلك لأنه ثبت عن النبي ﷺ أنه قال: لا تسافر امرأة إلا مع ذي محرم وهذا يعم سفر الحج وغيره، فليس لك السفر للحج إلا بمحرم، وفي إمكانك -إن شاء الله- أن يتيسر لك ذلك بالزوج، أو بأحد إخوانك إن كان لك إخوان، والحمد لله عذرك واضح شرعي، فإذا تيسر المحرم؛ فحجي، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذا كانت مع مجموعة من النساء سماحة الشيخ؟ الشيخ: ولو مع مجموعة، الصواب: أنها لا تحج إلا مع محرم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14825/حكم-سفر-المراة-للحج-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80401.mp3","categories":["شروط الحج","قضايا المرأة"]},{"id":16185,"question":"أولى أسئلة هذه الحلقة وصلت إلى البرنامج من المستمع (م. ل. ن) مصري يقيم في المملكة، أخونا له بعض الأسئلة في أحدها يقول: هل يصح الحج قبل سداد الدين؟ وجهونا جزاكم الله خيرًا.","title":"حكم حج المديون قبل قضاء دينه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا بأس، نعم يصح الحج، وإن كان الإنسان عليه دين، لكن كونه يبدأ بالدين أولى من الحج؛ لأن الحج لا يجب مع العجز، وإنما يجب مع الاستطاعة، والدين واجب القضاء، فعليك أن تبادر بالدين، إلا إذا كان عندك قدرة، تستطيع الحج، وقضاء الدين جميعًا؛ فالحمد لله، نعم. المقدم: جزاكم الله خيرًا؛ يقول: هل ما تبقى علي من أقساط يعتبر دينًا لا يصح الحج إلا بعد تسديده؟ الشيخ: الأقساط دين يجب أداؤه في وقته، فإذا أمكنك أن تحج بمال لا يضر الأقساط، فعليك الحج، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14867/حكم-حج-المديون-قبل-قضاء-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75101.mp3","categories":["شروط الحج"]},{"id":16281,"question":"المستمع أحمد محمد ضاحي يسأل ويقول: هذا العام في نيتي أن أحج -إن شاء الله تعالى- وسيكون معي ابني البالغ من العمر تسع سنوات ونصف، هل تجزئه هذه الحجة عن حجة الفريضة؟","title":"ما حكم حج الصبي؟","answer":"الجواب: لا، لا تجزئه حتى يحتلم، حتى يبلغ الحلم، لكن نافلة لك أجر، وله أجر.. لك أجر، وله أجر، يقول السائب بن يزيد : \"حج بي مع النبي ﷺ وأنا ابن سبع سنين\". ويقول ﷺ: أيما صبي حج، ثم بلغ الحنث يعني: الحلم فعليه أن يحج حجةً أخرى، وأيما عبد حج، ثم أعتق؛ فعليه أن يحج حجةً أخرى فحج المملوك نافلة، وحج الصبي نافلة، فإذا بلغ الحلم، واستطاع الحج؛ وجب عليه حج الفريضة، وهكذا العبد إذا أعتق، واستطاع الحج؛ وجب عليه حج الفريضة. وبلوغ الحلم يكون بأمور ثلاثة: أحدها: إكمال خمسة عشر سنة، إذا كمل خمسة عشر سنة؛ صار رجلًا، وهكذا المرأة. الثاني: إنبات الشعر الخشن حول الفرج، حول القبل، إذا أنبت الشعر حول القبل، ويسمى: شعر العانة، ويسمى: الشعرة، إذا نبت للرجل، أو المرأة هذا الشعر؛ صار الرجل مكلفًا، وصارت المرأة مكلفة، تجب عليهما الصلاة، وصوم رمضان، والحج إذا استطاع الحج والمرأة كذلك، بهذا الإنبات يكون مكلفًا، والمرأة تكون مكلفة. الثالث: إنزال المني، إذا أنزل الرجل المني عن شهوة، باحتلام، أو تفكير، أو ملامسة؛ صار بالغًا؛ صار رجلًا، وهكذا المرأة إذا أنزلت بالتفكير، أو بالاحتلام؛ صارت بالغة بهذا الإنزال، ولو ..... عشر سنين، أو تسع سنين، أو إحدى عشر سنة، أو ثلاثة عشر سنة، إذا بلغت تسعًا؛ فهي امرأة تصلح للزواج، وقد تحتلم، قد تنبت، قد تحيض أيضًا، وهي بنت عشر، أو فوق التسع، قد كملت التسع، قد تحيض، تقول عائشة -رضي الله عنها-: إذا بلغت الجارية تسع سنين؛ فهي امرأة والنبي ﷺ دخل بعائشة وهي ابنة تسع. هذه أمور ثلاثة: الأول: إكمال خمسة عشر سنة للرجل والمرأة. الثاني: إنبات الشعرة، إنبات الشعر الخشن حول الفرج، حول القبل من الرجل والمرأة جميعًا الشعرة. الثالث: إنزال المني عن شهوة من الرجل والمرأة جميعًا باحتلام، أو بغير احتلام، وفيه غسل أيضًا .. الغسل يكون الرجل مكلفًا، وتكون المرأة مكلفة بهذا الإنزال. وهناك أمر رابع للمرأة يخصها وهو الحيض، إذا حاضت؛ صارت امرأة، وهذا أمر رابع، فإذا حاضت وهي بنت تسع، أو عشر، أو أكثر تكون امرأة، أما الدم الذي تراه قبل التسع ما يكون عليه عمل، لابد يكون فوق التسع، تسع فأكثر، إذا رأت الحيض وهي بنت تسع، فأكثر؛ فهي امرأة، ولا تصلي عند وجود الحيض حتى تطهر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14972/ما-حكم-حج-الصبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80905.mp3","categories":["شروط الحج"]},{"id":16644,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين لم يذكر فيها اسمه، إنما له جمع من الأسئلة، يسأل سماحتكم فيقول: ما رأي سماحتكم فيمن يريد أداء الحج -حج الفريضة- وعليه ديون، أيها أولى: سداد هذه الديون؟ أم أداء الحج والعمرة؟ جزاكم الله خيرًا.","title":"حكم الحج لمن عليه دين","answer":"الجواب: يبدأ بالدين فيقضيه؛ لأن قضاء الدين متحتم، يلزمه أن يقضي الدين، والحج لا يلزمه إلا إذا استطاع بعد قضاء ديونه، فالواجب البداءة بقضاء الديون، وتسديدها، فإذا فرغ من قضاء الدين؛ يحج. المقصود: لا يلزمه الحج، ولا يشرع له الحج حتى يقضي دينه، يبدأ بأهل الدين، إلا إذا كانوا محصورين، وسمحوا له؛ فلا بأس، مثل محصورين، معروفين، وسمحوا له أن يحج، ويؤجل دينهم؛ فلا حرج في ذلك. المقدم: جزاكم الله خيرًا، ما رأي سماحتكم فيمن اشترى منزلًا، أو شقة بالتقسيط، هل ما تبقى عليه من باقي الثمن يعتبر دينًا؟ الشيخ: نعم إذا اشترى شقة، أو سيارة، أو أرضًا بالتقسيط فما قدمه معلوم، وما بقي في ذمته يسمى دينًا، ويسمى غارمًا إذ كان عاجزًا يعطى من الزكاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15377/حكم-الحج-لمن-عليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71707.mp3","categories":["شروط الحج"]},{"id":16829,"question":"من جمهورية مصر العربية رسالة بعثها أحد المستمعين يقول محمد حسن المتولي من أولاد ناصر يقول: أنا شاب متزوج، وأعيش وزوجتي مع الأسرة، وأعمل الآن في إحدى الدول الشقيقة، وما أكسبه من أجل الأسرة جميعًا والداي، وأشقائي، فهل يحق لي الحج دون إذن والداي، مع العلم أنهما لم يحجا بعد، جزاكم الله خيرًا.","title":"حكم الحج من المال الذي ينفق منه على الوالدين","answer":"الجواب: إذا كانت نفقتهما عليك، نفقتهم عليك، وأنهم في حاجة إلى هذا المال، وليس فيه فضل حتى تحج منه؛ فهم مقدمون، وأنت غير مستطيع؛ فأنفق عليهم، ولا حج عليك حتى تستطيع، أما إذا كان عندهم مال، عندهم قدرة، وهذا من باب المساعدة لهم؛ فعليك أن تحج من هذا المال الذي تستطيع به الحج، وأنت أعلم بالواقع، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15584/حكم-الحج-من-المال-الذي-ينفق-منه-على-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76316.mp3","categories":["شروط الحج"]},{"id":17440,"question":"رسالة وصلت من جمهورية مصر العربية، محافظة أسوان، وصاحبها هو المستمع سيد علي، يقول: هل لي أن أحج وأنا لم أتزوج بعد؟ جزاكم الله خيرًا.","title":"هل من شروط الحج أن يكون متزوجاً؟","answer":"الجواب: نعم. لا حرج في الحج وأنت لم تتزوج، إذا كنت تستطيع الحج؛ وجب عليك الحج، وإن كنت أعزب لم تزوج، أما إذا كنت لا تستطيع فالله يقول -جل وعلا-: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] والسبيل هو القدرة على المال الذي يوصلك إلى مكة ذهابًا وإيابًا، وإن كنت في حاجة للزواج، وتخاف الخطر فابدأ بالزواج؛ لأن الزواج أمره مهم، فإذا تيسر لك الزواج؛ فابدأ به، ولو أخرت الحجـ نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16304/هل-من-شروط-الحج-ان-يكون-متزوجا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83607.mp3","categories":["شروط الحج"]},{"id":17744,"question":"السائل حسن آدم له هذا السؤال يقول: هل الإنسان إذا كان عليه دين هل يصح حجه؟","title":"حكم حج من عليه دين","answer":"الجواب: نعم، يصح حجه لكن ينبغي له أن يبدأ بالدين، الدين أبدأ أهم حق المخلوقين أهم في هذا، والحج ما هو بواجب عليه إلا مع الاستطاعة وما دام مدين ليس عنده شيء يستطيع به قضاء الدين والحج فالله لم يوجب عليه الحج هذا من رحمة الله  قال تعالى: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا[آل عمران:97]. والذي عليه دين حال وليس عنده ما يستطيع به قضاء الدين والحج غير مستطيع وغير مكلف بالحج، فيبدأ بالدين، ويعطي أهله إذا كان دينًا حالًا ... يحج به يعطيه أهل الدين، فإن حج وتساهل ولم يعط أهل الدين حجه صحيح، ولكنه ترك ما ينبغي له، ترك الواجب عليه وهو البداءة بأهل الدين بحقوق الآدميين؛ لأنه ما يكون مستطيعًا إلا إذا وجد مالًا يفضل عن قضاء الدين الحال، ويستطيع به الحج، لكن لو خالف وحج ولم يوف الدين حجه صحيح والحمد لله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16706/حكم-حج-من-عليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77707.mp3","categories":["شروط الحج"]},{"id":17892,"question":"رسالة من أحد الإخوة المستمعين يقول: أنا سوداني أقيم في المملكة وأنوي أقضي فريضة الحج وذلك في الحج المقبل إن شاء الله ولأول مرة، ولكن علي دين يلزمني أن أسدد الدين ولو بطريقة المراسلة، وإذا لم أجد إنسانًا أرسل معه هذا المبلغ ماذا أفعل؟ جزاكم الله خيرًا.","title":"حكم حج المدين القادر على الوفاء","answer":"الجواب: تفعل ما تستطيع وتحج والحمد لله، ليس من شرط الحج أن لا يكون عليك دين مادمت قادرًا على الوفاء ولو بعد الحج الحمد لله، ترسله قبل الحج أو بعده وأنت على خير إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16928/حكم-حج-المدين-القادر-على-الوفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84607.mp3","categories":["شروط الحج"]},{"id":18405,"question":"هذه السائلة في آخر أسئلتها في رسالتها تستفسر من سماحتكم عن ذهاب المرأة بدون محرم إلى فريضة الحج، هل مثل هذا الحج مقبول أم لا؟","title":"حكم ذهاب المرأة إلى الحج بدون محرم","answer":"الجواب: إذا كانت في مكة لا بأس؛ لأنه ليس بسفر، إذا كانت في مكة وحجت مع الحريم فلا بأس، أما إذا كانت في سفر من جدة، من المدينة، من الرياض، من غير ذلك ليس لها أن تحج إلا بمحرم لقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم، أما إن كانت في مكة فمنى قريب، وعرفة قريب، وإذا كانت مع نساء طيبات فلا بأس. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17481/حكم-ذهاب-المراة-الى-الحج-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78415.mp3","categories":["شروط الحج"]},{"id":18932,"question":"لي أخ شقيق أكبر مني سنًا، له عندي مبلغ من المال، وأنا أرغب في الحج، هل لي أن أحج أولاً، ثم أسدد، أم أسدد ثم أحج؟ جزاكم الله خيرًا، ذلك لأن أخي ليس بفقير.","title":"حكم أداء الحج قبل قضاء الدين","answer":"الجواب: عليك أن تسدد الدين، الواجب أن تسدد الدين إذا كان حالًا، إلا إذا سمح، سمح لك فلا بأس، وإلا فالواجب أن تسدد الدين، والحج لا يجب عليك إلا مع الاستطاعة، والدين مقدم على الحج إذا كنت لا تستطيع الحج مع قضاء الدين، فقدم الدين، إلا إذا سمح أخوك أو غيره من أهل الدين سمحوا لك فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/18064/حكم-اداء-الحج-قبل-قضاء-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73623.mp3","categories":["شروط الحج"]},{"id":19148,"question":"أختنا أيضًا تقول: الطبيب نصحني بألا أحج أبدًا رغم أني أشعر بالقدرة على ذلك؟","title":"حكم من نصحه الطبيب بعدم الحج مع قدرته عليه","answer":"الجواب: إذا كنتِ تعلمين من نفسك القدرة فلا كلام للطبيب، ولا وجه لكلام الطبيب، إذا تيسر المحرم سافري للحج، واستعيني بالله، ولا تلتفتي إلى قول الطبيب وأنت تعلمين من نفسك القدرة، فالله يقول سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97]. ولما سئل الرسول ﷺ عن الإسلام قال: أن تشهد أن لا إله إلا الله، وأن محمدًا رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت إن استطعت إليه سبيلًا، فاستعيني بالله وحجي، ولا تسافري إلا مع محرم كالأخ والعم والخال، ونحو ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18332/حكم-من-نصحه-الطبيب-بعدم-الحج-مع-قدرته-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88604.mp3","categories":["شروط الحج"]},{"id":19513,"question":"من الجزائر أرسل السائل بهذا السؤال يقول: امرأة تنوي أداء فريضة الحج، وهي تبلغ من العمر خمسة وخمسين سنة، ومع العلم بأن الزوج سبق وأن أدى فريضة الحج، وهي تريد الحج بدون محرم ما حكم الشرع، وهل حجها صحيح، ومتى يسقط عنها الحج؟","title":"حكم الحج على المرأة التي ليس لها محرم","answer":"الجواب: لا يجوز لها الحج من دون محرم، لا الفريضة، ولا النافلة، إن حصل محرم فلا بأس وإلا فليس لها الحج، ولو الفريضة؛ لقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم فإذا وجد المحرم زوج، أو أخ، أو عم، أو خال، أو نحوه فلا بأس، وإلا فالحمد لله لها الأجر وإن جلست، تجتهد في العبادة في بلدها الصلاة، والقراءة، والصدقة، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/18766/حكم-الحج-على-المراة-التي-ليس-لها-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94615.mp3","categories":["شروط الحج"]}]
